import { ChecksIcon } from "@phosphor-icons/react";
import { Button } from "@pisagor/react";
import { Alert } from "@pisagor/react/alert";
export function Compound() {
  return (
    <Alert.Root variant="info">
      <ChecksIcon />
      <Alert.Title>Deployment successful</Alert.Title>
      <Alert.Description>
        You can now start building your next great project.
      </Alert.Description>
      <Alert.Action>
        <Button size="xs">Update</Button>
      </Alert.Action>
    </Alert.Root>
  );
}

import { MagicWandIcon } from "@phosphor-icons/react";
import { Alert } from "@pisagor/react/alert";

export function CustomColor() {
  return (
    <Alert
      className="border-purple-500/32 bg-purple-500/5 [&_svg]:text-purple-500"
      description="This alert uses a custom color."
      icon={<MagicWandIcon />}
      title="Custom color alert"
    />
  );
}

import { Alert } from "@pisagor/react/alert";

export function Default() {
  return (
    <Alert
      description="You can add icons to alerts to provide visual context and improve user experience."
      title="Icons improve context"
    />
  );
}

import {
  CheckCircleIcon,
  ChecksIcon,
  ClockCounterClockwiseIcon,
  WarningIcon,
} from "@phosphor-icons/react";
import { Alert } from "@pisagor/react/alert";

export function Variants() {
  return (
    <div className="flex flex-col gap-2">
      <Alert
        description="You can now start building your next great project."
        icon={<ChecksIcon />}
        title="Deployment successful"
        variant="default"
      />
      <Alert
        description="Your session has expired. Please log in again."
        icon={<WarningIcon />}
        title="Session expired"
        variant="destructive"
      />
      <Alert
        description="A new update is available. Review the update when you're ready."
        icon={<ClockCounterClockwiseIcon />}
        title="New update available"
        variant="info"
      />
      <Alert
        description="Your payment has been processed successfully. You will receive a receipt in your email."
        icon={<CheckCircleIcon />}
        title="Payment successful"
        variant="success"
      />
      <Alert
        description="Your storage is almost full. Consider upgrading your plan to avoid losing data."
        icon={<WarningIcon />}
        title="Storage almost full"
        variant="warning"
      />
    </div>
  );
}

import { ClockCounterClockwiseIcon } from "@phosphor-icons/react";
import { Button } from "@pisagor/react";
import { Alert } from "@pisagor/react/alert";
export function WithAction() {
  return (
    <Alert
      action={
        <>
          <Button size="xs" variant="ghost">
            Ignore
          </Button>
          <Button size="xs">Update</Button>
        </>
      }
      description="Review the update when you're ready."
      icon={<ClockCounterClockwiseIcon />}
      title="New update available"
    />
  );
}

import { SparkleIcon } from "@phosphor-icons/react";
import { Alert } from "@pisagor/react/alert";

export function WithIcon() {
  return (
    <Alert
      description="Icons can be added to alerts to provide visual context and improve user experience."
      icon={<SparkleIcon />}
      title="New feature available"
    />
  );
}

