import { ark } from "@ark-ui/react/factory";
import { announcementRecipe } from "@pisagor/recipes/announcement";
import type { ComponentProps, ReactNode } from "react";
import { AnnouncementContext, useAnnouncement } from "./announcement.context";

// #region Types
type AnnouncementTitleProps = ComponentProps<typeof ark.span>;

type AnnouncementRootProps = Omit<ComponentProps<typeof ark.div>, "title"> & {
  /**
   * The ARIA role of the announcement.
   *
   * @defaultValue "status"
   */
  role?: "status" | "alert";
  /**
   * Style recipe. Defaults to `announcementRecipe` from `@pisagor/recipes/announcement`.
   *
   * @defaultValue announcementRecipe
   */
  recipe?: typeof announcementRecipe;
};

export interface AnnouncementProps
  extends Omit<AnnouncementRootProps, "children"> {
  /** Optional badge or label rendered before the title. */
  badge?: ReactNode;
  /** Title content rendered inside `Announcement.Title`. */
  title?: ReactNode;
  /** Extra props forwarded to the announcement title element */
  titleProps?: Omit<AnnouncementTitleProps, "children" | "className">;
}
// #endregion

// #region Parts
export function AnnouncementRoot({
  role = "status",
  children,
  recipe = announcementRecipe,
  className,
  ...rest
}: AnnouncementRootProps) {
  const slots = recipe();

  return (
    <AnnouncementContext value={{ slots }}>
      <ark.div
        {...rest}
        className={slots.base({ className })}
        data-part="root"
        data-scope="announcement"
        role={role}
      >
        {" "}
        {children}
      </ark.div>
    </AnnouncementContext>
  );
}

export function AnnouncementTitle({
  className,
  ...rest
}: AnnouncementTitleProps) {
  const { slots } = useAnnouncement();

  return (
    <ark.span
      {...rest}
      className={slots.title({ className })}
      data-part="title"
      data-scope="announcement"
    />
  );
}
// #endregion

// #region Shorthand
export function AnnouncementShorthand({
  badge,
  title,
  titleProps,
  ...rest
}: AnnouncementProps) {
  return (
    <AnnouncementRoot {...rest}>
      {" "}
      {badge}
      {title !== undefined && (
        <AnnouncementTitle {...titleProps}>{title}</AnnouncementTitle>
      )}
    </AnnouncementRoot>
  );
}
// #endregion

// #region Display Names
AnnouncementRoot.displayName = "Announcement.Root";
AnnouncementTitle.displayName = "Announcement.Title";
AnnouncementShorthand.displayName = "Announcement";
// #endregion

import type { AnnouncementRecipe } from "@pisagor/recipes/announcement";
import { createContext } from "../../utils";

interface AnnouncementContextValue {
  slots: AnnouncementRecipe;
}

export const { AnnouncementContext, useAnnouncement } =
  createContext<AnnouncementContextValue>()({
    name: "Announcement",
  });

import {
  AnnouncementRoot,
  AnnouncementShorthand,
  AnnouncementTitle,
} from "./announcement";

export type { AnnouncementProps } from "./announcement";

export const Announcement = Object.assign(AnnouncementShorthand, {
  Root: AnnouncementRoot,
  Title: AnnouncementTitle,
});

