import { ark } from "@ark-ui/react/factory";
import { type BadgeVariantProps, badgeRecipe } from "@pisagor/recipes/badge";
import type { ComponentProps } from "react";

// #region Types
export type BadgeVariant = BadgeVariantProps["variant"];

export interface BadgeProps
  extends ComponentProps<typeof ark.span>,
    BadgeVariantProps {
  /**
   * Style recipe. Defaults to `badgeRecipe` from `@pisagor/recipes/badge`.
   *
   * @defaultValue badgeRecipe
   */
  recipe?: typeof badgeRecipe;
}
// #endregion

// #region Component
export function Badge({
  pill = false,
  size = "md",
  variant = "default",
  recipe = badgeRecipe,
  className,
  ...rest
}: BadgeProps) {
  return (
    <ark.span
      {...rest}
      className={recipe({ className, pill, size, variant })}
      data-part="root"
      data-scope="badge"
      data-size={size}
      data-variant={variant}
    />
  );
}
// #endregion

import { ark } from "@ark-ui/react/factory";
import {
  type TabListProps,
  Tabs as TabsPrimitive,
  type TabsRootProps,
  type TabTriggerProps,
} from "@ark-ui/react/tabs";
import {
  bottomNavigationItemRecipe,
  bottomNavigationRecipe,
} from "@pisagor/recipes/bottom-navigation";
import type { ComponentProps } from "react";
import {
  BottomNavigationContext,
  BottomNavigationItemContext,
  useBottomNavigation,
  useBottomNavigationItem,
} from "./bottom-navigation.context";

// #region Types
export interface BottomNavigationRootProps extends TabsRootProps {
  /**
   * Style recipe. Defaults to `bottomNavigationRecipe` from `@pisagor/recipes/bottom-navigation`.
   *
   * @defaultValue bottomNavigationRecipe
   */
  recipe?: typeof bottomNavigationRecipe;
}

export type BottomNavigationProps = BottomNavigationRootProps;

export type BottomNavigationListProps = TabListProps;

export interface BottomNavigationItemProps extends TabTriggerProps {
  /**
   * Style recipe. Defaults to `bottomNavigationItemRecipe` from `@pisagor/recipes/bottom-navigation`.
   *
   * @defaultValue bottomNavigationItemRecipe
   */
  itemRecipe?: typeof bottomNavigationItemRecipe;
}

export type BottomNavigationItemIconProps = ComponentProps<typeof ark.span>;

export type BottomNavigationItemLabelProps = ComponentProps<typeof ark.span>;
// #endregion

// #region Parts
export function BottomNavigationRoot({
  recipe = bottomNavigationRecipe,
  className,
  ...rest
}: BottomNavigationRootProps) {
  const slots = recipe();

  return (
    <BottomNavigationContext value={{ slots }}>
      <TabsPrimitive.Root {...rest} className={slots.base({ className })} />
    </BottomNavigationContext>
  );
}

export function BottomNavigationList({
  className,
  ...rest
}: BottomNavigationListProps) {
  const { slots } = useBottomNavigation();

  return <TabsPrimitive.List {...rest} className={slots.list({ className })} />;
}

export function BottomNavigationItem({
  children,
  itemRecipe = bottomNavigationItemRecipe,
  className,
  ...rest
}: BottomNavigationItemProps) {
  const slots = itemRecipe();

  return (
    <BottomNavigationItemContext value={{ slots }}>
      <TabsPrimitive.Trigger {...rest} className={slots.base({ className })}>
        {children}
      </TabsPrimitive.Trigger>
    </BottomNavigationItemContext>
  );
}

export function BottomNavigationItemIcon({
  className,
  ...rest
}: BottomNavigationItemIconProps) {
  const { slots } = useBottomNavigationItem();

  return (
    <ark.span
      {...rest}
      aria-hidden
      className={slots.icon({ className })}
      data-part="item-icon"
      data-scope="bottom-navigation"
    />
  );
}

export function BottomNavigationItemLabel({
  className,
  ...rest
}: BottomNavigationItemLabelProps) {
  const { slots } = useBottomNavigationItem();

  return (
    <ark.span
      {...rest}
      className={slots.label({ className })}
      data-part="item-label"
      data-scope="bottom-navigation"
    />
  );
}
// #endregion

// #region Display Names
BottomNavigationRoot.displayName = "BottomNavigation";
BottomNavigationList.displayName = "BottomNavigation.List";
BottomNavigationItem.displayName = "BottomNavigation.Item";
BottomNavigationItemIcon.displayName = "BottomNavigation.ItemIcon";
BottomNavigationItemLabel.displayName = "BottomNavigation.ItemLabel";
// #endregion

import type {
  BottomNavigationItemRecipe,
  BottomNavigationRecipe,
} from "@pisagor/recipes/bottom-navigation";
import { createContext } from "../../utils";

interface BottomNavigationContextValue {
  slots: BottomNavigationRecipe;
}

interface BottomNavigationItemContextValue {
  slots: BottomNavigationItemRecipe;
}

export const { BottomNavigationContext, useBottomNavigation } =
  createContext<BottomNavigationContextValue>()({
    name: "BottomNavigation",
  });

export const { BottomNavigationItemContext, useBottomNavigationItem } =
  createContext<BottomNavigationItemContextValue>()({
    name: "BottomNavigationItem",
  });

import {
  BottomNavigationItem,
  BottomNavigationItemIcon,
  BottomNavigationItemLabel,
  BottomNavigationList,
  BottomNavigationRoot,
} from "./bottom-navigation";

export type {
  BottomNavigationItemIconProps,
  BottomNavigationItemLabelProps,
  BottomNavigationItemProps,
  BottomNavigationListProps,
  BottomNavigationProps,
  BottomNavigationRootProps,
} from "./bottom-navigation";

export const BottomNavigation = Object.assign(BottomNavigationRoot, {
  Item: BottomNavigationItem,
  ItemIcon: BottomNavigationItemIcon,
  ItemLabel: BottomNavigationItemLabel,
  List: BottomNavigationList,
});

