import { Carousel } from "@pisagor/react/carousel";
import { numberedSlides } from "./helpers";

export function Autoplay() {
  return <Carousel autoplay loop slides={numberedSlides(8)} />;
}

import { Carousel } from "@pisagor/react/carousel";
import { numberedSlides } from "./helpers";

export function Compound() {
  const slides = numberedSlides(8);

  return (
    <Carousel.Root slideCount={slides.length}>
      <Carousel.Control>
        <Carousel.PrevTrigger>Previous</Carousel.PrevTrigger>
        <Carousel.NextTrigger>Next</Carousel.NextTrigger>
      </Carousel.Control>
      <Carousel.ItemGroup>
        {slides.map((slide, index) => (
          <Carousel.Item index={index} key={slide.key}>
            {slide.content}
          </Carousel.Item>
        ))}
      </Carousel.ItemGroup>
    </Carousel.Root>
  );
}

import { Carousel } from "@pisagor/react/carousel";
import { useState } from "react";
import { numberedSlides } from "./helpers";

export function Controlled() {
  const [page, setPage] = useState(0);
  const slides = numberedSlides(8);

  return (
    <div className="flex flex-col gap-2">
      <Carousel
        onPageChange={({ page }) => setPage(page)}
        page={page}
        slides={slides}
      />
      <p className="text-center text-muted-foreground text-sm">
        Current page: {page + 1} of 5
      </p>
    </div>
  );
}

import { Carousel } from "@pisagor/react/carousel";
import { numberedSlides } from "./helpers";

export function Default() {
  return <Carousel slides={numberedSlides(8)} />;
}

import { Carousel } from "@pisagor/react/carousel";
import { numberedSlides } from "./helpers";

export function Loop() {
  return <Carousel autoplay loop slides={numberedSlides(4)} />;
}

import { Carousel } from "@pisagor/react/carousel";
import { numberedSlides } from "./helpers";

export function MouseDrag() {
  return <Carousel allowMouseDrag slides={numberedSlides(8)} />;
}

import { Carousel } from "@pisagor/react/carousel";
import { imageSlides } from "./helpers";

export function OrientationHorizontal() {
  return <Carousel slides={imageSlides()} />;
}

import { Carousel } from "@pisagor/react/carousel";
import { imageSlides } from "./helpers";

export function OrientationVertical() {
  return (
    <Carousel className="h-40" orientation="vertical" slides={imageSlides()} />
  );
}

import { Card } from "@pisagor/react";
import { Carousel } from "@pisagor/react/carousel";
export function SlidesPerPage() {
  return (
    <Carousel
      slides={Array.from({ length: 16 }, (_, slideIndex) => ({
        content: (
          <Card>
            <Card.Content className="flex h-40 items-center justify-center">
              <span className="font-semibold text-2xl">{slideIndex + 1}</span>
            </Card.Content>
          </Card>
        ),
        key: `slide-${slideIndex + 1}`,
      }))}
      slidesPerPage={3}
    />
  );
}

import { Carousel } from "@pisagor/react/carousel";
import { numberedSlides } from "./helpers";

export function Spacing() {
  return (
    <Carousel slides={numberedSlides(8)} slidesPerPage={2} spacing="64px" />
  );
}

import { Carousel } from "@pisagor/react/carousel";
import { imageSources } from "./helpers";

export function ThumbnailIndicatorVertical() {
  const slides = imageSources();

  return (
    <Carousel.Root
      className="h-40"
      loop
      orientation="vertical"
      slideCount={slides.length}
    >
      <Carousel.Control className="relative">
        <Carousel.PrevTrigger>Previous</Carousel.PrevTrigger>
        <Carousel.NextTrigger>Next</Carousel.NextTrigger>

        <Carousel.ItemGroup>
          {slides.map((slide, index) => (
            <Carousel.Item index={index} key={slide.src}>
              <img alt={slide.alt} height={300} src={slide.src} width={500} />
            </Carousel.Item>
          ))}
        </Carousel.ItemGroup>
      </Carousel.Control>
      <Carousel.IndicatorGroup className="ml-4">
        {slides.map((slide, index) => (
          <Carousel.Indicator
            className="size-10 rounded-md"
            index={index}
            key={slide.src}
          >
            <img alt={slide.alt} height={40} src={slide.src} width={40} />
          </Carousel.Indicator>
        ))}
      </Carousel.IndicatorGroup>
    </Carousel.Root>
  );
}

import { Carousel } from "@pisagor/react/carousel";
import { imageSources } from "./helpers";

export function ThumbnailIndicator() {
  const slides = imageSources();

  return (
    <Carousel.Root loop slideCount={slides.length}>
      <Carousel.Control className="relative">
        <Carousel.PrevTrigger>Previous</Carousel.PrevTrigger>
        <Carousel.NextTrigger>Next</Carousel.NextTrigger>

        <Carousel.ItemGroup>
          {slides.map((slide, index) => (
            <Carousel.Item index={index} key={slide.src}>
              <img alt={slide.alt} height={300} src={slide.src} width={500} />
            </Carousel.Item>
          ))}
        </Carousel.ItemGroup>
      </Carousel.Control>
      <Carousel.IndicatorGroup className="mt-4">
        {slides.map((slide, index) => (
          <Carousel.Indicator
            className="size-10 rounded-md"
            index={index}
            key={slide.src}
          >
            <img alt={slide.alt} height={40} src={slide.src} width={40} />
          </Carousel.Indicator>
        ))}
      </Carousel.IndicatorGroup>
    </Carousel.Root>
  );
}

