export function ColumnFilters() {
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([]);
  const [globalFilter, setGlobalFilter] = useState("");
  const columns = useUserColumns();

  const columnsWithFilters = useMemo<ColumnDef<User>[]>(
    () =>
      columns.map((column) => {
        if (!("accessorKey" in column)) {
          return column;
        }

        if (column.accessorKey === "role" || column.accessorKey === "status") {
          return {
            ...column,
            header: ({ column: tableColumn }) => {
              const values = Array.from(
                tableColumn.getFacetedUniqueValues()?.keys() ?? [],
              ).sort() as string[];

              return (
                <ColumnFilterHeader label={column.header as string}>
                  <ColumnFilterSelect
                    items={["All", ...values]}
                    onValueChange={(value) => {
                      const next = Array.isArray(value) ? value[0] : value;
                      tableColumn.setFilterValue(
                        next === "All" ? undefined : next,
                      );
                    }}
                    value={[
                      (tableColumn.getFilterValue() as string | undefined) ??
                        "All",
                    ]}
                  />
                </ColumnFilterHeader>
              );
            },
          };
        }

        if (column.accessorKey === "name" || column.accessorKey === "email") {
          return {
            ...column,
            header: ({ column: tableColumn }) => (
              <ColumnFilterHeader label={column.header as string}>
                <Input
                  aria-label={`Filter ${String(column.accessorKey)}`}
                  onChange={(event) =>
                    tableColumn.setFilterValue(event.target.value)
                  }
                  placeholder="Filter…"
                  size="sm"
                  value={
                    (tableColumn.getFilterValue() as string | undefined) ?? ""
                  }
                />
              </ColumnFilterHeader>
            ),
          };
        }

        if (
          column.accessorKey === "department" ||
          column.accessorKey === "joinedAt"
        ) {
          return {
            ...column,
            header: () => (
              <ColumnFilterHeader label={column.header as string} />
            ),
          };
        }

        return column;
      }),
    [columns],
  );

  return (
    <DataGridShell>
      <DataGrid<User>
        columns={columnsWithFilters}
        data={allUsers}
        initialState={{ pagination: { pageIndex: 0, pageSize: 8 } }}
        onColumnFiltersChange={setColumnFilters}
        onGlobalFilterChange={setGlobalFilter}
        state={{ columnFilters, globalFilter }}
      >
        <DataGrid.Toolbar>
          <div className="flex flex-wrap items-center gap-2">
            <InputGroup>
              <InputGroup.Addon>
                <MagnifyingGlassIcon />
              </InputGroup.Addon>
              <InputGroup.Input
                aria-label="Search all columns"
                onChange={(event) => setGlobalFilter(event.target.value)}
                placeholder="Global search…"
                value={globalFilter}
              />
            </InputGroup>
            <Button
              onClick={() => {
                setColumnFilters([]);
                setGlobalFilter("");
              }}
              size="sm"
              variant="outline"
            >
              <FunnelIcon />
              Clear filters
            </Button>
          </div>
        </DataGrid.Toolbar>
        <DataGridView colSpan={6} filterHead />
        <DataGridPaginationBar<User> />
      </DataGrid>
    </DataGridShell>
  );
}

