export function ColumnPinning() {
  const [columnPinning, setColumnPinning] = useState<ColumnPinningState>({
    end: ["actions"],
    start: ["name"],
  });

  const columns = useMemo<ColumnDef<User>[]>(
    () => [
      {
        accessorKey: "name",
        cell: ({ row }) => (
          <span className="font-medium">{row.original.name}</span>
        ),
        header: "Name",
        meta: { pinned: "start" as const },
      },
      { accessorKey: "email", header: "Email" },
      { accessorKey: "role", header: "Role" },
      { accessorKey: "department", header: "Department" },
      {
        accessorKey: "status",
        cell: ({ row }) => (
          <Badge
            className="capitalize"
            variant={statusVariants[row.original.status]}
          >
            {row.original.status}
          </Badge>
        ),
        header: "Status",
      },
      {
        cell: () => (
          <Button aria-label="Row actions" size="icon-sm" variant="ghost">
            <DotsThreeVerticalIcon />
          </Button>
        ),
        header: "",
        id: "actions",
        meta: { pinned: "end" as const },
        size: 48,
      },
    ],
    [],
  );

  return (
    <DataGridShell>
      <DataGrid<User>
        columns={columns}
        data={allUsers.slice(0, 10)}
        enableColumnPinning
        onColumnPinningChange={setColumnPinning}
        state={{ columnPinning }}
      >
        <DataGrid.Toolbar>
          <p className="text-muted-foreground text-sm">
            Name pinned start, actions pinned end — scroll horizontally to see
            pinning.
          </p>
        </DataGrid.Toolbar>
        <Table className="min-w-240">
          <Table.Header>
            <DataGrid.Header>
              <DataGrid.HeaderRow>
                {columns.map((column) => {
                  const id =
                    "accessorKey" in column
                      ? String(column.accessorKey)
                      : column.id;
                  const pinned = (
                    column.meta as { pinned?: "start" | "end" } | undefined
                  )?.pinned;

                  return (
                    <DataGrid.Head
                      className={
                        pinned === "start"
                          ? "sticky inset-s-0 z-10 bg-background shadow-[inset_-1px_0_0_var(--border)]"
                          : pinned === "end"
                            ? "sticky inset-e-0 z-10 bg-background shadow-[inset_1px_0_0_var(--border)]"
                            : undefined
                      }
                      columnId={id}
                      key={id}
                    />
                  );
                })}
              </DataGrid.HeaderRow>
            </DataGrid.Header>
          </Table.Header>
          <Table.Body>
            <DataGrid.Body empty={<DataGrid.Empty colSpan={6} />}>
              <DataGrid.Row>
                {columns.map((column) => {
                  const id =
                    "accessorKey" in column
                      ? String(column.accessorKey)
                      : column.id;
                  const pinned = (
                    column.meta as { pinned?: "start" | "end" } | undefined
                  )?.pinned;

                  return (
                    <DataGrid.Cell
                      className={
                        pinned === "start"
                          ? "sticky inset-s-0 z-10 bg-background shadow-[inset_-1px_0_0_var(--border)]"
                          : pinned === "end"
                            ? "sticky inset-e-0 z-10 bg-background shadow-[inset_1px_0_0_var(--border)]"
                            : undefined
                      }
                      columnId={id}
                      key={id}
                    />
                  );
                })}
              </DataGrid.Row>
            </DataGrid.Body>
          </Table.Body>
        </Table>
      </DataGrid>
    </DataGridShell>
  );
}

