export function MultiGrouping() {
  const [grouping, setGrouping] = useState<GroupingState>([
    "department",
    "role",
  ]);
  const [expanded, setExpanded] = useState<ExpandedState>(true);

  const columns = useMemo<ColumnDef<User>[]>(
    () => [
      {
        accessorKey: "department",
        aggregationFn: "count",
        cell: ({ row }) => {
          if (row.getIsGrouped()) {
            return (
              <button
                className="inline-flex items-center gap-1.5 font-medium"
                onClick={row.getToggleExpandedHandler()}
                type="button"
              >
                {row.getIsExpanded() ? (
                  <CaretDownIcon className="size-3.5" />
                ) : (
                  <CaretRightIcon className="size-3.5" />
                )}
                {String(row.groupingValue)}
              </button>
            );
          }

          return row.original.department;
        },
        header: "Department",
      },
      {
        accessorKey: "role",
        aggregatedCell: ({ getValue }) => `${getValue()} users`,
        aggregationFn: "count",
        cell: ({ row }) =>
          row.getIsGrouped()
            ? `${row.groupingValue} (${row.subRows?.length ?? 0})`
            : row.original.role,
        header: "Role",
      },
      {
        accessorKey: "name",
        cell: ({ row }) => (row.getIsGrouped() ? null : row.original.name),
        header: "Name",
      },
      {
        accessorKey: "status",
        cell: ({ row }) =>
          row.getIsGrouped() ? null : (
            <Badge
              className="capitalize"
              variant={statusVariants[row.original.status]}
            >
              {row.original.status}
            </Badge>
          ),
        header: "Status",
