        <DataGrid.Toolbar>
          <p className="text-muted-foreground text-sm">
            Nested grouping by department, then role.
          </p>
        </DataGrid.Toolbar>
        <DataGridView colSpan={4} />
      </DataGrid>
    </DataGridShell>
  );
