import { ark } from "@ark-ui/react/factory";
import { fileInputRecipe } from "@pisagor/recipes/file-input";
import {
  type FormControlGroupShellVariantProps,
  formControlGroupShellRecipe,
} from "@pisagor/recipes/form-control";
import {
  type ChangeEventHandler,
  type ComponentProps,
  useRef,
  useState,
} from "react";
import {
  InputGroupAddon,
  InputGroupButton,
  InputGroupText,
  type InputGroupTextProps,
} from "../input-group/input-group-core";
import { useFormControlSurface } from "../surface/use-form-control-surface";
import { FileInputContext, useFileInput } from "./file-input.context";

// #region Types
type FormControlVariant = "primary" | "secondary";

type FileInputVariantProps = FormControlGroupShellVariantProps;

type NativeFileInputProps = Omit<
  ComponentProps<"input">,
  "defaultValue" | "onChange" | "size" | "type" | "value"
>;

type FileInputRootProps = ComponentProps<typeof ark.div> &
  FileInputVariantProps & {
    /** Disables the control and sets `data-disabled` on the root. */
    disabled?: boolean;
    /**
     * Style recipe. Defaults to `fileInputRecipe` from `@pisagor/recipes/file-input`.
     *
     * @defaultValue fileInputRecipe
     */
    recipe?: typeof fileInputRecipe;
  };

export interface FileInputProps
  extends NativeFileInputProps,
    FileInputVariantProps {
  /** Marks the control invalid for styling and assistive tech. */
  invalid?: boolean;
  /** Label for the browse button. */
  browseLabel?: string;
  /** Text shown when no file is selected. */
  placeholder?: string;
  onChange?: ChangeEventHandler<HTMLInputElement>;
  /** Called with accepted files when the selection changes. */
  onFilesChange?: (files: File[]) => void;
  /** Alias for `onFilesChange`; matches `FileUpload` callback naming. */
  onValueChange?: (files: File[]) => void;
  /**
   * Style recipe. Defaults to `fileInputRecipe` from `@pisagor/recipes/file-input`.
   *
   * @defaultValue fileInputRecipe
   */
  recipe?: typeof fileInputRecipe;
}

interface FileInputControlProps extends ComponentProps<"input"> {}

interface FileInputLabelProps extends InputGroupTextProps {}
// #endregion

// #region Helpers
function getSelectedFiles(input: HTMLInputElement): File[] {
  return input.files ? Array.from(input.files) : [];
}

function formatFileLabel(files: File[]): string | undefined {
  if (files.length === 0) {
    return undefined;
  }

  if (files.length === 1) {
    return files[0]?.name;
  }

  return `${files.length} files selected`;
}
// #endregion

// #region Parts
function FileInputRoot({
  size = "md",
  variant: variantProp,
  disabled,
  children,
  recipe = fileInputRecipe,
  className,
  ...rest
}: FileInputRootProps) {
  const resolved = {
    surfaceVariant: useFormControlSurface(),
    variant: variantProp ?? ("primary" as FormControlVariant),
  };
  const shellArgs = {
    surfaceVariant: resolved.surfaceVariant,
    variant: resolved.variant,
  };
  const controlProps = { "data-variant": resolved.variant };
  const slots = recipe();

  return (
    <FileInputContext value={{ slots }}>
      <ark.div
        {...rest}
        {...controlProps}
        className={formControlGroupShellRecipe({
          className,
          size,
          ...shellArgs,
        })}
        data-disabled={disabled ? true : undefined}
        data-part="root"
        data-scope="file-input"
        data-size={size}
        role="group"
      >
        {children}
      </ark.div>
    </FileInputContext>
  );
}

function FileInputControl({ className, ...rest }: FileInputControlProps) {
  const { slots } = useFileInput();

  return (
    <input
      {...rest}
      className={slots.control({ className })}
      data-part="control"
      data-scope="file-input"
      type="file"
    />
  );
}

function FileInputLabel({ children, className, ...rest }: FileInputLabelProps) {
  const { slots } = useFileInput();

  return (
    <InputGroupText {...rest} className={slots.label({ className })}>
      {children}
    </InputGroupText>
  );
}
// #endregion

// #region Closed
export function FileInput({
  size = "md",
  variant,
  accept,
  disabled,
  invalid,
  multiple,
  name,
  required,
  browseLabel = "Choose file",
  capture,
  id,
  placeholder = "No file chosen",
  ref,
  onChange,
  onFilesChange,
  onValueChange,
  recipe,
  className,
  ...rest
}: FileInputProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [fileLabel, setFileLabel] = useState<string>();

  const setRefs = (node: HTMLInputElement | null) => {
    inputRef.current = node;

    if (typeof ref === "function") {
      ref(node);
      return;
    }

    if (ref) {
      ref.current = node;
    }
  };

  const openPicker = () => {
    inputRef.current?.click();
  };

  const changeHandler: ChangeEventHandler<HTMLInputElement> = (event) => {
    onChange?.(event);
    const files = getSelectedFiles(event.currentTarget);
    onFilesChange?.(files);
    onValueChange?.(files);
    setFileLabel(formatFileLabel(files));
  };

  return (
    <FileInputRoot
      className={className}
      disabled={disabled}
      recipe={recipe}
      size={size}
      variant={variant}
    >
      <FileInputControl
        {...rest}
        accept={accept}
        aria-invalid={invalid || undefined}
        capture={capture}
        data-invalid={invalid || undefined}
        disabled={disabled}
        id={id}
        multiple={multiple}
        name={name}
        onChange={changeHandler}
        ref={setRefs}
        required={required}
      />

      <InputGroupAddon align="inline-start">
        <InputGroupButton
          disabled={disabled}
          onClick={openPicker}
          type="button"
        >
          {browseLabel}
        </InputGroupButton>
      </InputGroupAddon>

      <FileInputLabel onClick={disabled ? undefined : openPicker}>
        {fileLabel ?? placeholder}
      </FileInputLabel>
    </FileInputRoot>
  );
}
// #endregion

// #region Display Names
FileInputRoot.displayName = "FileInput.Root";
FileInputControl.displayName = "FileInput.Control";
FileInputLabel.displayName = "FileInput.Label";
FileInput.displayName = "FileInput";
// #endregion

import type { FileInputRecipe } from "@pisagor/recipes/file-input";
import { createContext } from "../../utils";

interface FileInputContextValue {
  slots: FileInputRecipe;
}

export const { FileInputContext, useFileInput } =
  createContext<FileInputContextValue>()({
    name: "FileInput",
  });

