import { ark } from "@ark-ui/react/factory";
import type {
  FileUploadClearTriggerProps,
  FileUploadItemGroupProps,
  FileUploadItemNameProps,
  FileUploadItemPreviewProps,
  FileUploadItemProps,
  FileUploadItemSizeTextProps,
  FileUploadDropzoneProps as FileUploadPrimitiveDropzoneProps,
  FileUploadRootProps as FileUploadPrimitiveRootProps,
  FileUploadTriggerProps,
} from "@ark-ui/react/file-upload";
import {
  FileUpload as FileUploadPrimitive,
  useFileUploadContext,
} from "@ark-ui/react/file-upload";
import { UploadIcon, XIcon } from "@phosphor-icons/react";
import {
  fileUploadItemRecipe,
  fileUploadRecipe,
} from "@pisagor/recipes/file-upload";
import { formControlZoneRecipe } from "@pisagor/recipes/form-control";
import { cn } from "@pisagor/utils";
import type { ComponentProps } from "react";
import { Button } from "../button";
import { useFormControlSurface } from "../surface/use-form-control-surface";
import {
  FileUploadContext,
  FileUploadItemContext,
  useFileUpload,
  useFileUploadItem,
} from "./file-upload.context";

// #region Types
type FormControlVariant = "primary" | "secondary";

export interface FileUploadItemRootProps extends FileUploadItemProps {
  /**
   * Style recipe. Defaults to `fileUploadItemRecipe` from `@pisagor/recipes/file-upload`.
   *
   * @defaultValue fileUploadItemRecipe
   */
  itemRecipe?: typeof fileUploadItemRecipe;
}

export type FileUploadListProps = Omit<FileUploadItemRootProps, "file">;

export interface FileUploadRootProps extends FileUploadPrimitiveRootProps {
  onValueChange?: (value: File[]) => void;
  /**
   * Style recipe. Defaults to `fileUploadRecipe` from `@pisagor/recipes/file-upload`.
   *
   * @defaultValue fileUploadRecipe
   */
  recipe?: typeof fileUploadRecipe;
}

export interface FileUploadDropzoneProps
  extends FileUploadPrimitiveDropzoneProps {
  /** Visual shell variant. Defaults to `primary`. */
  variant?: FormControlVariant;
}

export type FileUploadItemPreviewImageProps = ComponentProps<
  typeof FileUploadPrimitive.ItemPreviewImage
>;

export type FileUploadItemSizeProps = FileUploadItemSizeTextProps;

export type FileUploadItemDeleteTriggerProps = ComponentProps<
  typeof FileUploadPrimitive.ItemDeleteTrigger
>;

export type FileUploadDropzoneIconProps = ComponentProps<typeof ark.div>;

export type FileUploadTitleProps = ComponentProps<typeof ark.div>;

export type FileUploadDescriptionProps = ComponentProps<typeof ark.div>;

export type FileUploadHelperProps = ComponentProps<typeof ark.div>;
// #endregion

// #region Parts
export function FileUploadRoot({
  children,
  onFileChange,
  onValueChange,
  recipe = fileUploadRecipe,
  className,
  ...rest
}: FileUploadRootProps) {
  const slots = recipe();

  return (
    <FileUploadContext value={{ slots }}>
      <FileUploadPrimitive.Root
        {...rest}
        className={slots.base({ className })}
        onFileChange={(details) => {
          onFileChange?.(details);
          onValueChange?.(details.acceptedFiles);
        }}
      >
        {children}

        <FileUploadPrimitive.HiddenInput />
      </FileUploadPrimitive.Root>
    </FileUploadContext>
  );
}

export function FileUploadTrigger(props: FileUploadTriggerProps) {
  return <FileUploadPrimitive.Trigger {...props} />;
}

export function FileUploadDropzone({
  variant: variantProp,
  className,
  ...rest
}: FileUploadDropzoneProps) {
  const resolved = {
    surfaceVariant: useFormControlSurface(),
    variant: variantProp ?? ("primary" as FormControlVariant),
  };
  const shellArgs = {
    surfaceVariant: resolved.surfaceVariant,
    variant: resolved.variant,
  };
  const controlProps = { "data-variant": resolved.variant };
  const { slots } = useFileUpload();

  return (
    <FileUploadPrimitive.Dropzone
      {...rest}
      {...controlProps}
      className={cn(
        formControlZoneRecipe({ ...shellArgs }),
        slots.dropzone(),
        className,
      )}
    />
  );
}

export function FileUploadDropzoneIcon({
  children,
  className,
  ...rest
}: FileUploadDropzoneIconProps) {
  const { slots } = useFileUpload();

  return (
    <ark.div
      {...rest}
      className={slots.dropzoneIcon({ className })}
      data-part="dropzone-icon"
      data-scope="file-upload"
    >
      {children || <UploadIcon />}
    </ark.div>
  );
}

export function FileUploadTitle({ className, ...rest }: FileUploadTitleProps) {
  const { slots } = useFileUpload();

  return (
    <ark.div
      {...rest}
      className={slots.title({ className })}
      data-part="title"
      data-scope="file-upload"
    />
  );
}

export function FileUploadDescription({
  className,
  ...rest
}: FileUploadDescriptionProps) {
  const { slots } = useFileUpload();

  return (
    <ark.div
      {...rest}
      className={slots.description({ className })}
      data-part="title"
      data-scope="file-upload"
    />
  );
}

export function FileUploadHelper({
  className,
  ...rest
}: FileUploadHelperProps) {
  const { slots } = useFileUpload();

  return (
    <ark.div
      {...rest}
      className={slots.helper({ className })}
      data-part="dropzone-helper"
      data-scope="file-upload"
    />
  );
}

export function FileUploadItemGroup(props: FileUploadItemGroupProps) {
  return <FileUploadPrimitive.ItemGroup {...props} />;
}

export function FileUploadList({
  className,
  itemRecipe = fileUploadItemRecipe,
  ...rest
}: FileUploadListProps) {
  const fileUpload = useFileUploadContext();
  const { slots } = useFileUpload();
  const itemSlots = itemRecipe();

  const files = fileUpload.acceptedFiles;

  if (files.length === 0) {
    return null;
  }

  return (
    <FileUploadItemGroup className={slots.itemGroup()}>
      {files.map((file, index) => {
        const isImage = file.type.startsWith("image/");

        const key = `${file.name}-${index}`;

        const extension = file.name.split(".").pop();

        return (
          <FileUploadItem
            {...rest}
            className={itemSlots.listItem({ className })}
            file={file}
            itemRecipe={itemRecipe}
            key={key}
          >
            <FileUploadItemPreview
              {...(isImage ? { type: "image/*" } : { type: ".*" })}
              className={itemSlots.listPreview()}
            >
              {isImage ? (
                <FileUploadItemPreviewImage />
              ) : (
                <span className={itemSlots.extension()}>{extension}</span>
              )}
            </FileUploadItemPreview>

            <div className={itemSlots.content()}>
              <FileUploadItemName />
              <FileUploadItemSize />
            </div>

            <FileUploadItemDeleteTrigger asChild>
              <Button
                aria-label="Remove file"
                className={itemSlots.deleteButton()}
                size="icon-xs"
                variant="ghost"
              >
                <XIcon aria-hidden />
              </Button>
            </FileUploadItemDeleteTrigger>
          </FileUploadItem>
        );
      })}
    </FileUploadItemGroup>
  );
}

export function FileUploadItem({
  children,
  itemRecipe = fileUploadItemRecipe,
  className,
  ...rest
}: FileUploadItemRootProps) {
  const slots = itemRecipe();

  return (
    <FileUploadItemContext value={{ slots }}>
      <FileUploadPrimitive.Item {...rest} className={slots.base({ className })}>
        {children}
      </FileUploadPrimitive.Item>
    </FileUploadItemContext>
  );
}

export function FileUploadItemPreview({
  className,
  ...rest
}: FileUploadItemPreviewProps) {
  const { slots } = useFileUploadItem();

  return (
    <FileUploadPrimitive.ItemPreview
      {...rest}
      className={slots.preview({ className })}
    />
  );
}

export function FileUploadItemPreviewImage({
  className,
  ...rest
}: FileUploadItemPreviewImageProps) {
  const { slots } = useFileUploadItem();

  return (
    <FileUploadPrimitive.ItemPreviewImage
      {...rest}
      className={slots.previewImage({ className })}
    />
  );
}

export function FileUploadItemName({
  className,
  ...rest
}: FileUploadItemNameProps) {
  const { slots } = useFileUploadItem();

  return (
    <FileUploadPrimitive.ItemName
      {...rest}
      className={slots.name({ className })}
    />
  );
}

export function FileUploadItemSize({
  className,
  ...rest
}: FileUploadItemSizeProps) {
  const { slots } = useFileUploadItem();

  return (
    <FileUploadPrimitive.ItemSizeText
      {...rest}
      className={slots.size({ className })}
    />
  );
}

export function FileUploadItemDeleteTrigger({
  className,
  ...rest
}: FileUploadItemDeleteTriggerProps) {
  const { slots } = useFileUploadItem();

  return (
    <FileUploadPrimitive.ItemDeleteTrigger
      {...rest}
      className={slots.deleteTrigger({ className })}
    />
  );
}

export function FileUploadClearTrigger(props: FileUploadClearTriggerProps) {
  return <FileUploadPrimitive.ClearTrigger {...props} />;
}
// #endregion

// #region Display Names
FileUploadRoot.displayName = "FileUpload";
FileUploadTrigger.displayName = "FileUpload.Trigger";
FileUploadDropzone.displayName = "FileUpload.Dropzone";
FileUploadDropzoneIcon.displayName = "FileUpload.DropzoneIcon";
FileUploadTitle.displayName = "FileUpload.Title";
FileUploadDescription.displayName = "FileUpload.Description";
FileUploadHelper.displayName = "FileUpload.Helper";
FileUploadItemGroup.displayName = "FileUpload.ItemGroup";
FileUploadList.displayName = "FileUpload.List";
FileUploadItem.displayName = "FileUpload.Item";
FileUploadItemPreview.displayName = "FileUpload.ItemPreview";
FileUploadItemPreviewImage.displayName = "FileUpload.ItemPreviewImage";
FileUploadItemName.displayName = "FileUpload.ItemName";
FileUploadItemSize.displayName = "FileUpload.ItemSize";
FileUploadItemDeleteTrigger.displayName = "FileUpload.ItemDeleteTrigger";
FileUploadClearTrigger.displayName = "FileUpload.ClearTrigger";
// #endregion

import type {
  FileUploadItemRecipe,
  FileUploadRecipe,
} from "@pisagor/recipes/file-upload";
import { createContext } from "../../utils";

interface FileUploadContextValue {
  slots: FileUploadRecipe;
}

interface FileUploadItemContextValue {
  slots: FileUploadItemRecipe;
}

export const { FileUploadContext, useFileUpload } =
  createContext<FileUploadContextValue>()({
    name: "FileUpload",
  });

export const { FileUploadItemContext, useFileUploadItem } =
  createContext<FileUploadItemContextValue>()({
    name: "FileUploadItem",
  });

import { ark } from "@ark-ui/react/factory";
import type {
  FloatingPanelCloseTriggerProps,
  FloatingPanelControlProps,
  FloatingPanelDragTriggerProps,
  FloatingPanelHeaderProps,
  FloatingPanelBodyProps as FloatingPanelPrimitiveBodyProps,
  FloatingPanelContentProps as FloatingPanelPrimitiveContentProps,
  FloatingPanelRootProps as FloatingPanelPrimitiveRootProps,
  FloatingPanelResizeTriggerProps,
  FloatingPanelStageTriggerProps,
  FloatingPanelTitleProps,
  FloatingPanelTriggerProps,
} from "@ark-ui/react/floating-panel";
import { FloatingPanel as FloatingPanelPrimitive } from "@ark-ui/react/floating-panel";
import { Portal } from "@ark-ui/react/portal";
import { ArrowsOutIcon, CornersInIcon, MinusIcon } from "@phosphor-icons/react";
import { floatingPanelRecipe } from "@pisagor/recipes/floating-panel";
import type { ComponentProps } from "react";
import { Button, type ButtonProps } from "../button";
import { ScrollArea } from "../scroll-area";
import {
  FloatingPanelContext,
  useFloatingPanel,
} from "./floating-panel.context";

// #region Types
export interface FloatingPanelRootProps
  extends FloatingPanelPrimitiveRootProps {
  /**
   * Style recipe. Defaults to `floatingPanelRecipe` from `@pisagor/recipes/floating-panel`.
   *
   * @defaultValue floatingPanelRecipe
   */
  recipe?: typeof floatingPanelRecipe;
}

export interface FloatingPanelContentProps
  extends FloatingPanelPrimitiveContentProps {
  /**
   * Whether to enable a resizable panel.
   *
   * @defaultValue true
   */
  resizable?: boolean;
}

export type FloatingPanelMinimizeProps = Omit<
  FloatingPanelStageTriggerProps,
  "stage"
> &
  ButtonProps;

export type FloatingPanelMaximizeProps = FloatingPanelMinimizeProps;

export type FloatingPanelRestoreProps = FloatingPanelMinimizeProps;

export interface FloatingPanelBodyProps
  extends FloatingPanelPrimitiveBodyProps {
  /**
   * Whether to add a fade effect to the scroll area.
   *
   * @defaultValue false
   */
  scrollFade?: boolean;
}

export type FloatingPanelFooterProps = ComponentProps<typeof ark.div>;
// #endregion

// #region Parts
export function FloatingPanelRoot({
  children,
  recipe = floatingPanelRecipe,
  ...rest
}: FloatingPanelRootProps) {
  const slots = recipe();

  return (
    <FloatingPanelContext value={{ slots }}>
      <FloatingPanelPrimitive.Root {...rest}>
        {children}
      </FloatingPanelPrimitive.Root>
    </FloatingPanelContext>
  );
}

export function FloatingPanelTrigger(props: FloatingPanelTriggerProps) {
  return <FloatingPanelPrimitive.Trigger {...props} />;
}

export function FloatingPanelContent({
  children,
  resizable = true,
  className,
  ...rest
}: FloatingPanelContentProps) {
  const { slots = floatingPanelRecipe() } = useFloatingPanel() ?? {};

  return (
    <Portal>
      <FloatingPanelPrimitive.Positioner className={slots.positioner()}>
        <FloatingPanelPrimitive.Content
          {...rest}
          className={slots.content({ className })}
        >
          {children}

          {resizable && (
            <>
              <FloatingPanelResizeTrigger axis="n" />
              <FloatingPanelResizeTrigger axis="e" />
              <FloatingPanelResizeTrigger axis="w" />
              <FloatingPanelResizeTrigger axis="s" />
              <FloatingPanelResizeTrigger axis="ne" />
              <FloatingPanelResizeTrigger axis="se" />
              <FloatingPanelResizeTrigger axis="sw" />
              <FloatingPanelResizeTrigger axis="nw" />
            </>
          )}
        </FloatingPanelPrimitive.Content>
      </FloatingPanelPrimitive.Positioner>
    </Portal>
  );
}

export function FloatingPanelDragTrigger(props: FloatingPanelDragTriggerProps) {
  return <FloatingPanelPrimitive.DragTrigger {...props} />;
}

export function FloatingPanelHeader({
  children,
  className,
  ...rest
}: FloatingPanelHeaderProps) {
  const { slots = floatingPanelRecipe() } = useFloatingPanel() ?? {};

  return (
    <FloatingPanelDragTrigger>
      <FloatingPanelPrimitive.Header
        {...rest}
        className={slots.header({ className })}
      >
        {children}
      </FloatingPanelPrimitive.Header>
    </FloatingPanelDragTrigger>
  );
}

export function FloatingPanelControl({
  children,
  className,
  ...rest
}: FloatingPanelControlProps) {
  const { slots = floatingPanelRecipe() } = useFloatingPanel() ?? {};

  return (
    <FloatingPanelPrimitive.Control
      {...rest}
      className={slots.control({ className })}
    >
      {children}
    </FloatingPanelPrimitive.Control>
  );
}

export function FloatingPanelMinimize({
  size = "icon-xs",
  variant = "ghost",
  ...rest
}: FloatingPanelMinimizeProps) {
  return (
    <FloatingPanelPrimitive.StageTrigger {...rest} asChild stage="minimized">
      <Button aria-label="Minimize" size={size} variant={variant}>
        <MinusIcon />
      </Button>
    </FloatingPanelPrimitive.StageTrigger>
  );
}

export function FloatingPanelMaximize({
  size = "icon-xs",
  variant = "ghost",
  ...rest
}: FloatingPanelMaximizeProps) {
  return (
    <FloatingPanelPrimitive.StageTrigger {...rest} asChild stage="maximized">
      <Button aria-label="Maximize" size={size} variant={variant}>
        <ArrowsOutIcon />
      </Button>
    </FloatingPanelPrimitive.StageTrigger>
  );
}

export function FloatingPanelRestore({
  size = "icon-xs",
  variant = "outline",
  ...rest
}: FloatingPanelRestoreProps) {
  const { slots = floatingPanelRecipe() } = useFloatingPanel() ?? {};

  return (
    <FloatingPanelPrimitive.StageTrigger {...rest} asChild stage="default">
      <Button aria-label="Restore" size={size} variant={variant}>
        <CornersInIcon className={slots.maximizedIcon()} />
        <ArrowsOutIcon className={slots.minimizedIcon()} />
      </Button>
    </FloatingPanelPrimitive.StageTrigger>
  );
}

export function FloatingPanelTitle({
  children,
  className,
  ...rest
}: FloatingPanelTitleProps) {
  const { slots = floatingPanelRecipe() } = useFloatingPanel() ?? {};

  return (
    <FloatingPanelPrimitive.Title
      {...rest}
      className={slots.title({ className })}
    >
      {children}
    </FloatingPanelPrimitive.Title>
  );
}

export function FloatingPanelResizeTrigger(
  props: FloatingPanelResizeTriggerProps,
) {
  return <FloatingPanelPrimitive.ResizeTrigger {...props} />;
}

export function FloatingPanelStageTrigger(
  props: FloatingPanelStageTriggerProps,
) {
  return <FloatingPanelPrimitive.StageTrigger {...props} />;
}

export function FloatingPanelCloseTrigger(
  props: FloatingPanelCloseTriggerProps,
) {
  return <FloatingPanelPrimitive.CloseTrigger {...props} />;
}

export function FloatingPanelBody({
  scrollFade = false,
  children,
  className,
  ...rest
}: FloatingPanelBodyProps) {
  const { slots = floatingPanelRecipe() } = useFloatingPanel() ?? {};

  return (
    <ScrollArea scrollFade={scrollFade}>
      <FloatingPanelPrimitive.Body
        {...rest}
        className={slots.body({ className })}
      >
        {children}
      </FloatingPanelPrimitive.Body>
    </ScrollArea>
  );
}

export function FloatingPanelFooter({
  children,
  className,
  ...rest
}: FloatingPanelFooterProps) {
  const { slots = floatingPanelRecipe() } = useFloatingPanel() ?? {};

  return (
    <ark.div
      {...rest}
      className={slots.footer({ className })}
      data-part="footer"
      data-scope="floating-panel"
    >
      {children}
    </ark.div>
  );
}
// #endregion

// #region Display Names
FloatingPanelRoot.displayName = "FloatingPanel";
FloatingPanelTrigger.displayName = "FloatingPanel.Trigger";
FloatingPanelContent.displayName = "FloatingPanel.Content";
FloatingPanelDragTrigger.displayName = "FloatingPanel.DragTrigger";
FloatingPanelHeader.displayName = "FloatingPanel.Header";
FloatingPanelControl.displayName = "FloatingPanel.Control";
FloatingPanelMinimize.displayName = "FloatingPanel.Minimize";
FloatingPanelMaximize.displayName = "FloatingPanel.Maximize";
FloatingPanelRestore.displayName = "FloatingPanel.Restore";
FloatingPanelTitle.displayName = "FloatingPanel.Title";
FloatingPanelResizeTrigger.displayName = "FloatingPanel.ResizeTrigger";
FloatingPanelStageTrigger.displayName = "FloatingPanel.StageTrigger";
FloatingPanelCloseTrigger.displayName = "FloatingPanel.CloseTrigger";
FloatingPanelBody.displayName = "FloatingPanel.Body";
FloatingPanelFooter.displayName = "FloatingPanel.Footer";
// #endregion

import type { FloatingPanelRecipe } from "@pisagor/recipes/floating-panel";
import { createContext } from "../../utils";

export interface FloatingPanelContextValue {
  /** Slot class recipes from `floatingPanelRecipe`. */
  slots: FloatingPanelRecipe;
}

export const { FloatingPanelContext, useFloatingPanel } =
  createContext<FloatingPanelContextValue>()({
    name: "FloatingPanel",
    strict: false,
  });

