import { ark } from "@ark-ui/react/factory";
import {
  type PinInputInputProps,
  PinInput as PinInputPrimitive,
  type PinInputRootProps,
} from "@ark-ui/react/pin-input";
import { inputOtpRecipe } from "@pisagor/recipes/input-otp";
import type { ComponentProps } from "react";
import { Input, type InputProps } from "../input/input";
import { InputOTPContext, useInputOTP } from "./input-otp.context";

// #region Types
export type InputOTPRootProps = Omit<PinInputRootProps, "onValueChange"> &
  Pick<InputProps, "size" | "variant">;

export interface InputOTPProps extends InputOTPRootProps {
  onValueChange?: (value: string[]) => void;
  /**
   * Style recipe. Defaults to `inputOtpRecipe` from `@pisagor/recipes/input-otp`.
   *
   * @defaultValue inputOtpRecipe
   */
  recipe?: typeof inputOtpRecipe;
}

export type InputOTPSlotProps = PinInputInputProps &
  Pick<InputProps, "variant">;

export type InputOTPSeparatorProps = ComponentProps<typeof ark.hr>;
// #endregion

// #region Parts
export function InputOTPRoot({
  variant,
  children,
  otp = true,
  placeholder,
  onValueChange,
  recipe = inputOtpRecipe,
  className,
  ...rest
}: InputOTPProps) {
  const slots = recipe();

  return (
    <InputOTPContext value={{ slots }}>
      <PinInputPrimitive.Root
        {...rest}
        className={slots.base()}
        onValueChange={
          onValueChange ? (details) => onValueChange(details.value) : undefined
        }
        otp={otp}
        placeholder={placeholder ?? ""}
      >
        <PinInputPrimitive.Control className={slots.control({ className })}>
          {children}
        </PinInputPrimitive.Control>

        <PinInputPrimitive.HiddenInput />
      </PinInputPrimitive.Root>
    </InputOTPContext>
  );
}

export function InputOTPSlot({
  variant,
  className,
  ...rest
}: InputOTPSlotProps) {
  const { slots } = useInputOTP();

  return (
    <PinInputPrimitive.Input {...rest} asChild>
      <Input className={slots.input({ className })} variant={variant} />
    </PinInputPrimitive.Input>
  );
}

export function InputOTPSeparator({
  className,
  ...rest
}: InputOTPSeparatorProps) {
  const { slots } = useInputOTP();

  return (
    <ark.hr
      {...rest}
      className={slots.separator({ className })}
      data-part="separator"
      data-scope="input-otp"
    />
  );
}
// #endregion

// #region Display Names
InputOTPRoot.displayName = "InputOTP";
InputOTPSlot.displayName = "InputOTP.Slot";
InputOTPSeparator.displayName = "InputOTP.Separator";
// #endregion

import type { InputOtpRecipe } from "@pisagor/recipes/input-otp";
import { createContext } from "../../utils";

interface InputOTPContextValue {
  slots: InputOtpRecipe;
}

export const { InputOTPContext, useInputOTP } =
  createContext<InputOTPContextValue>()({
    name: "InputOTP",
  });

import { InputOTPRoot, InputOTPSeparator, InputOTPSlot } from "./input-otp";

export type {
  InputOTPProps,
  InputOTPRootProps,
  InputOTPSeparatorProps,
  InputOTPSlotProps,
} from "./input-otp";

export const InputOTP = Object.assign(InputOTPRoot, {
  Separator: InputOTPSeparator,
  Slot: InputOTPSlot,
});

