import type {
  MarqueeContentProps,
  MarqueeEdgeProps,
  MarqueeItemProps,
  MarqueeRootProps as MarqueePrimitiveRootProps,
} from "@ark-ui/react/marquee";
import { Marquee as MarqueePrimitive } from "@ark-ui/react/marquee";
import { marqueeRecipe } from "@pisagor/recipes/marquee";
import type { ReactNode } from "react";
import { Children, isValidElement } from "react";
import { MarqueeContext, useMarquee } from "./marquee.context";

// #region Types
export interface MarqueeRootProps
  extends Omit<MarqueePrimitiveRootProps, "side"> {
  /**
   *
   * @defaultValue "horizontal"
   */
  orientation?: "horizontal" | "vertical";
  /**
   * Whether to show the edges of the marquee
   *
   * @defaultValue true
   */
  showEdges?: boolean;
  /**
   * Style recipe. Defaults to `marqueeRecipe` from `@pisagor/recipes/marquee`.
   *
   * @defaultValue marqueeRecipe
   */
  recipe?: typeof marqueeRecipe;
}

export interface MarqueeProps extends Omit<MarqueeRootProps, "children"> {
  /** Items to auto-render inside a MarqueeContent; each item is wrapped in MarqueeItem */
  items?: ReactNode[];
}

// #endregion

// #region Parts
export function MarqueeRoot({
  orientation = "horizontal",
  showEdges = true,
  children,
  spacing = "16px",
  speed = 50,
  recipe = marqueeRecipe,
  className,
  ...rest
}: MarqueeRootProps) {
  const slots = recipe();
  const side = orientation === "horizontal" ? "start" : "bottom";

  return (
    <MarqueeContext value={{ slots }}>
      <MarqueePrimitive.Root
        {...rest}
        className={slots.base({ className })}
        data-orientation={orientation}
        side={side}
        spacing={spacing}
        speed={speed}
      >
        {children}
        {showEdges && (
          <>
            <MarqueeEdge
              side={orientation === "horizontal" ? "start" : "top"}
            />
            <MarqueeEdge
              side={orientation === "horizontal" ? "end" : "bottom"}
            />
          </>
        )}
      </MarqueePrimitive.Root>
    </MarqueeContext>
  );
}

export function MarqueeContent({ className, ...rest }: MarqueeContentProps) {
  const { slots } = useMarquee();

  return (
    <MarqueePrimitive.Viewport className={slots.viewport()}>
      <MarqueePrimitive.Content
        {...rest}
        className={slots.content({ className })}
      />
    </MarqueePrimitive.Viewport>
  );
}

export function MarqueeItem({ className, ...rest }: MarqueeItemProps) {
  const { slots } = useMarquee();

  return (
    <MarqueePrimitive.Item {...rest} className={slots.item({ className })} />
  );
}

export function MarqueeEdge({ className, ...rest }: MarqueeEdgeProps) {
  const { slots } = useMarquee();

  return (
    <MarqueePrimitive.Edge {...rest} className={slots.edge({ className })} />
  );
}
// #endregion

// #region Shorthand
export function MarqueeShorthand({ items, ...rest }: MarqueeProps) {
  return (
    <MarqueeRoot {...rest}>
      {items && (
        <MarqueeContent>
          {Children.toArray(items).map((item) =>
            isValidElement(item) ? (
              <MarqueeItem key={item.key}>{item}</MarqueeItem>
            ) : (
              <MarqueeItem key={String(item)}>{item}</MarqueeItem>
            ),
          )}
        </MarqueeContent>
      )}
    </MarqueeRoot>
  );
}
// #endregion

// #region Display Names
MarqueeRoot.displayName = "Marquee.Root";
MarqueeContent.displayName = "Marquee.Content";
MarqueeItem.displayName = "Marquee.Item";
MarqueeEdge.displayName = "Marquee.Edge";
MarqueeShorthand.displayName = "Marquee";
// #endregion

import type { MarqueeRecipe } from "@pisagor/recipes/marquee";
import { createContext } from "../../utils";

interface MarqueeContextValue {
  slots: MarqueeRecipe;
}

export const { MarqueeContext, useMarquee } =
  createContext<MarqueeContextValue>()({
    name: "Marquee",
  });

import {
  MarqueeContent,
  MarqueeEdge,
  MarqueeItem,
  MarqueeRoot,
  MarqueeShorthand,
} from "./marquee";

export type {
  MarqueeContentProps,
  MarqueeEdgeProps,
  MarqueeItemProps,
} from "@ark-ui/react/marquee";

export type { MarqueeProps, MarqueeRootProps } from "./marquee";

export const Marquee = Object.assign(MarqueeShorthand, {
  Content: MarqueeContent,
  Edge: MarqueeEdge,
  Item: MarqueeItem,
  Root: MarqueeRoot,
});

import { ark } from "@ark-ui/react/factory";
import {
  type MenuItemVariantProps,
  menuItemRecipe,
  menuRecipe,
} from "@pisagor/recipes/menu";
import { cn } from "@pisagor/utils";
import type { ComponentProps } from "react";
import { MenuContext, useMenu } from "./menu.context";

// #region Types
export interface MenuRootProps extends ComponentProps<typeof ark.nav> {
  /**
   * Style recipe. Defaults to `menuRecipe` from `@pisagor/recipes/menu`.
   *
   * @defaultValue menuRecipe
   */
  recipe?: typeof menuRecipe;
}

export type MenuPartProps = ComponentProps<typeof ark.div>;

export type MenuListProps = ComponentProps<typeof ark.ul>;

export interface MenuItemProps
  extends ComponentProps<typeof ark.button>,
    MenuItemVariantProps {
  /**
   * Style recipe. Defaults to `menuItemRecipe` from `@pisagor/recipes/menu`.
   *
   * @defaultValue menuItemRecipe
   */
  recipe?: typeof menuItemRecipe;
}

export interface MenuLinkProps extends ComponentProps<typeof ark.a> {
  /** Whether the link represents the current page */
  active?: boolean;
}

export type MenuGroupLabelProps = ComponentProps<typeof ark.div>;

export type MenuSeparatorProps = ComponentProps<typeof ark.div>;

export type MenuShortcutProps = ComponentProps<typeof ark.span>;
// #endregion

// #region Parts
export function MenuRoot({
  "aria-label": ariaLabel = "Menu",
  children,
  recipe = menuRecipe,
  className,
  ...rest
}: MenuRootProps) {
  const slots = recipe();

  return (
    <MenuContext value={{ slots }}>
      <ark.nav
        {...rest}
        aria-label={ariaLabel}
        className={slots.base({ className })}
        data-part="root"
        data-scope="menu"
      >
        {children}
      </ark.nav>
    </MenuContext>
  );
}

export function MenuList({ className, ...rest }: MenuListProps) {
  const { slots } = useMenu();

  return (
    <ark.ul
      {...rest}
      className={slots.list({ className })}
      data-part="list"
      data-scope="menu"
      role="list"
    />
  );
}

export function MenuGroup({ className, ...rest }: MenuPartProps) {
  const { slots } = useMenu();

  return (
    <ark.div
      {...rest}
      className={slots.group({ className })}
      data-part="group"
      data-scope="menu"
      role="group"
    />
  );
}

export function MenuGroupLabel({ className, ...rest }: MenuGroupLabelProps) {
  const { slots } = useMenu();

  return (
    <ark.div
      {...rest}
      className={slots.groupLabel({ className })}
      data-part="group-label"
      data-scope="menu"
    />
  );
}

export function MenuItem({
  variant = "default",
  type = "button",
  recipe = menuItemRecipe,
  className,
  ...rest
}: MenuItemProps) {
  const { slots } = useMenu();

  return (
    <ark.li
      className={slots.wrapper()}
      data-part="item-wrapper"
      data-scope="menu"
      role="none"
    >
      <ark.button
        {...rest}
        className={cn(recipe({ variant }), className)}
        data-part="item"
        data-scope="menu"
        data-variant={variant}
        type={type}
      />
    </ark.li>
  );
}

export function MenuLink({
  active = false,
  className,
  ...rest
}: MenuLinkProps) {
  const { slots } = useMenu();

  return (
    <ark.li
      className={slots.wrapper()}
      data-part="item-wrapper"
      data-scope="menu"
      role="none"
    >
      <ark.a
        {...rest}
        aria-current={active ? "page" : undefined}
        className={slots.link({ className })}
        data-active={active}
        data-part="link"
        data-scope="menu"
      />
    </ark.li>
  );
}

export function MenuSeparator({ className, ...rest }: MenuSeparatorProps) {
  const { slots } = useMenu();

  return (
    <ark.div
      {...rest}
      aria-hidden
      className={slots.separator({ className })}
      data-part="separator"
      data-scope="menu"
      role="separator"
    />
  );
}

export function MenuShortcut({ className, ...rest }: MenuShortcutProps) {
  const { slots } = useMenu();

  return (
    <ark.span
      {...rest}
      className={slots.shortcut({ className })}
      data-part="shortcut"
      data-scope="menu"
    />
  );
}
// #endregion

// #region Display Names
MenuRoot.displayName = "Menu";
MenuList.displayName = "Menu.List";
MenuGroup.displayName = "Menu.Group";
MenuGroupLabel.displayName = "Menu.GroupLabel";
MenuItem.displayName = "Menu.Item";
MenuLink.displayName = "Menu.Link";
MenuSeparator.displayName = "Menu.Separator";
MenuShortcut.displayName = "Menu.Shortcut";
// #endregion

import type { MenuRecipe } from "@pisagor/recipes/menu";
import { createContext } from "../../utils";

interface MenuContextValue {
  slots: MenuRecipe;
}

export const { MenuContext, useMenu } = createContext<MenuContextValue>()({
  name: "Menu",
});

import {
  MenuGroup,
  MenuGroupLabel,
  MenuItem,
  MenuLink,
  MenuList,
  MenuRoot,
  MenuSeparator,
  MenuShortcut,
} from "./menu";

export type {
  MenuGroupLabelProps,
  MenuItemProps,
  MenuLinkProps,
  MenuListProps,
  MenuPartProps,
  MenuRootProps,
  MenuSeparatorProps,
  MenuShortcutProps,
} from "./menu";

export const Menu = Object.assign(MenuRoot, {
  Group: MenuGroup,
  GroupLabel: MenuGroupLabel,
  Item: MenuItem,
  Link: MenuLink,
  List: MenuList,
  Root: MenuRoot,
  Separator: MenuSeparator,
  Shortcut: MenuShortcut,
});

