// #endregion

// #region Display Names
SidebarProvider.displayName = "Sidebar.Provider";
SidebarRoot.displayName = "Sidebar";
SidebarTrigger.displayName = "Sidebar.Trigger";
SidebarRail.displayName = "Sidebar.Rail";
