import type {
  SwitchControlProps,
  SwitchHiddenInputProps,
  SwitchRootProps as SwitchPrimitiveRootProps,
  SwitchThumbProps,
} from "@ark-ui/react/switch";
import { Switch as SwitchPrimitive } from "@ark-ui/react/switch";
import { type SwitchRecipeSlot, switchRecipe } from "@pisagor/recipes/switch";

import type { VariantClassNames } from "../../internal/types";
import { useFormControlSurface } from "../surface/use-form-control-surface";
import { SwitchContext, useSwitch } from "./switch.context";

// #region Types
type FormControlVariant = "primary" | "secondary";

type SwitchClassNames = VariantClassNames<SwitchRecipeSlot>;

type SwitchRootProps = SwitchPrimitiveRootProps & {
  /** Visual shell variant. Defaults to `primary`. */
  variant?: FormControlVariant;
  /**
   * Style recipe. Defaults to `switchRecipe` from `@pisagor/recipes/switch`.
   *
   * @defaultValue switchRecipe
   */
  recipe?: typeof switchRecipe;
};

export interface SwitchProps extends Omit<SwitchRootProps, "children"> {
  onValueChange?: (value: boolean) => void;
  /** Slot class names */
  classNames?: SwitchClassNames;
  /** Extra props forwarded to the switch control element */
  controlProps?: Omit<SwitchControlProps, "children" | "className">;
  /** Extra props forwarded to the hidden input element (e.g. tabIndex) */
  hiddenInputProps?: Omit<SwitchHiddenInputProps, "className">;
  /** Extra props forwarded to the switch thumb element */
  thumbProps?: Omit<SwitchThumbProps, "children" | "className">;
}
// #endregion

// #region Parts
function SwitchRoot({
  variant: variantProp,
  children,
  recipe = switchRecipe,
  className,
  ...rest
}: SwitchRootProps) {
  const resolved = {
    surfaceVariant: useFormControlSurface(),
    variant: variantProp ?? ("primary" as FormControlVariant),
  };
  const shellArgs = {
    surfaceVariant: resolved.surfaceVariant,
    variant: resolved.variant,
  };
  const controlShellProps = { "data-variant": resolved.variant };
  const slots = recipe({ ...shellArgs });

  return (
    <SwitchContext value={{ slots }}>
      <SwitchPrimitive.Root
        {...rest}
        {...controlShellProps}
        className={slots.base({ className })}
      >
        {children}
      </SwitchPrimitive.Root>
    </SwitchContext>
  );
}

function SwitchControl({ children, className, ...rest }: SwitchControlProps) {
  const { slots } = useSwitch();

  return (
    <SwitchPrimitive.Control {...rest} className={slots.control({ className })}>
      {children}
    </SwitchPrimitive.Control>
  );
}

function SwitchThumb({ className, ...rest }: SwitchThumbProps) {
  const { slots } = useSwitch();

  return (
    <SwitchPrimitive.Thumb {...rest} className={slots.thumb({ className })} />
  );
}

function SwitchHiddenInput(props: SwitchHiddenInputProps) {
  return <SwitchPrimitive.HiddenInput {...props} />;
}
// #endregion

// #region Closed
export function Switch({
  variant,
  controlProps,
  hiddenInputProps,
  thumbProps,
  onCheckedChange,
  onValueChange,
  className,
  classNames,
  ...rest
}: SwitchProps) {
  const handleCheckedChange =
    onCheckedChange || onValueChange
      ? (
          details: Parameters<
            NonNullable<SwitchRootProps["onCheckedChange"]>
          >[0],
        ) => {
          onCheckedChange?.(details);
          onValueChange?.(details.checked === true);
        }
      : undefined;

  return (
    <SwitchRoot
      {...rest}
      className={className}
      onCheckedChange={handleCheckedChange}
      variant={variant}
    >
      <SwitchControl {...controlProps} className={classNames?.control}>
        <SwitchThumb {...thumbProps} className={classNames?.thumb} />
      </SwitchControl>

      <SwitchHiddenInput {...hiddenInputProps} />
    </SwitchRoot>
  );
}
// #endregion

// #region Display Names
SwitchRoot.displayName = "Switch.Root";
SwitchControl.displayName = "Switch.Control";
SwitchThumb.displayName = "Switch.Thumb";
SwitchHiddenInput.displayName = "Switch.HiddenInput";
Switch.displayName = "Switch";
// #endregion

import type { SwitchRecipe } from "@pisagor/recipes/switch";
import { createContext } from "../../utils";

interface SwitchContextValue {
  slots: SwitchRecipe;
}

export const { SwitchContext, useSwitch } = createContext<SwitchContextValue>()(
  {
    name: "Switch",
  },
);

export type {
  SwitchControlProps,
  SwitchHiddenInputProps,
  SwitchThumbProps,
} from "@ark-ui/react/switch";

export type { SwitchProps } from "./switch";
export { Switch } from "./switch";

