import { ark } from "@ark-ui/react/factory";
import {
  type TimelineVariantProps,
  timelineItemRecipe,
  timelineRecipe,
} from "@pisagor/recipes/timeline";
import type { ComponentProps, ReactNode } from "react";
import { TimelineItemContext, useTimelineItem } from "./timeline.context";

// #region Types
export interface TimelineRootProps
  extends ComponentProps<typeof ark.ol>,
    TimelineVariantProps {
  /**
   * Style recipe. Defaults to `timelineRecipe` from `@pisagor/recipes/timeline`.
   *
   * @defaultValue timelineRecipe
   */
  recipe?: typeof timelineRecipe;
}

export interface TimelineItemProps extends ComponentProps<typeof ark.li> {
  /**
   * Style recipe. Defaults to `timelineItemRecipe` from `@pisagor/recipes/timeline`.
   *
   * @defaultValue timelineItemRecipe
   */
  itemRecipe?: typeof timelineItemRecipe;
}

export type TimelineIndicatorProps = ComponentProps<typeof ark.div>;

export type TimelineContentProps = ComponentProps<typeof ark.div>;

export type TimelineTitleProps = ComponentProps<typeof ark.div>;

export type TimelineDescriptionProps = ComponentProps<typeof ark.div>;

export type TimelineSeparatorProps = ComponentProps<typeof ark.div>;

export interface TimelinePresetItem {
  /** Stable key for the item when title is not a string. */
  id?: string;
  title: ReactNode;
  description?: ReactNode;
  indicator?: ReactNode;
}

export interface TimelineProps extends Omit<TimelineRootProps, "children"> {
  items?: TimelinePresetItem[];
}
// #endregion

// #region Parts
export function TimelineRoot({
  orientation = "vertical",
  recipe = timelineRecipe,
  className,
  ...rest
}: TimelineRootProps) {
  return (
    <ark.ol
      {...rest}
      className={recipe({ className, orientation })}
      data-orientation={orientation}
      data-part="root"
      data-scope="timeline"
    />
  );
}

export function TimelineItem({
  children,
  itemRecipe = timelineItemRecipe,
  className,
  ...rest
}: TimelineItemProps) {
  const slots = itemRecipe();

  return (
    <TimelineItemContext value={{ slots }}>
      <ark.li
        {...rest}
        className={slots.base({ className })}
        data-part="item"
        data-scope="timeline"
      >
        {children}
      </ark.li>
    </TimelineItemContext>
  );
}

export function TimelineIndicator({
  children,
  className,
  ...rest
}: TimelineIndicatorProps) {
  const { slots } = useTimelineItem();

  return (
    <ark.div
      {...rest}
      className={slots.indicator({ className })}
      data-part="indicator"
      data-scope="timeline"
    >
      {children}
    </ark.div>
  );
}

export function TimelineSeparator({
  className,
  ...rest
}: TimelineSeparatorProps) {
  const { slots } = useTimelineItem();

  return (
    <ark.div
      {...rest}
      aria-hidden="true"
      className={slots.separator({ className })}
      data-part="separator"
      data-scope="timeline"
    />
  );
}

export function TimelineContent({ className, ...rest }: TimelineContentProps) {
  const { slots } = useTimelineItem();

  return (
    <ark.div
      {...rest}
      className={slots.content({ className })}
      data-part="content"
      data-scope="timeline"
    />
  );
}

export function TimelineTitle({ className, ...rest }: TimelineTitleProps) {
  const { slots } = useTimelineItem();

  return (
    <ark.div
      {...rest}
      className={slots.title({ className })}
      data-part="title"
      data-scope="timeline"
    />
  );
}

export function TimelineDescription({
  className,
  ...rest
}: TimelineDescriptionProps) {
  const { slots } = useTimelineItem();

  return (
    <ark.div
      {...rest}
      className={slots.description({ className })}
      data-part="description"
      data-scope="timeline"
    />
  );
}
// #endregion

// #region Shorthand
export function TimelineShorthand({ items = [], ...rest }: TimelineProps) {
  return (
    <TimelineRoot {...rest}>
      {items.map((item, index) => {
        const key =
          item.id ??
          (typeof item.title === "string" || typeof item.title === "number"
            ? String(item.title)
            : `timeline-item-${index}`);

        return (
          <TimelineItem key={key}>
            <TimelineSeparator />

            <TimelineIndicator>{item.indicator}</TimelineIndicator>

            <TimelineContent>
              <TimelineTitle>{item.title}</TimelineTitle>

              {item.description ? (
                <TimelineDescription>{item.description}</TimelineDescription>
              ) : null}
            </TimelineContent>
          </TimelineItem>
        );
      })}
    </TimelineRoot>
  );
}
// #endregion

// #region Display Names
TimelineRoot.displayName = "Timeline.Root";
TimelineItem.displayName = "Timeline.Item";
TimelineIndicator.displayName = "Timeline.Indicator";
TimelineSeparator.displayName = "Timeline.Separator";
TimelineContent.displayName = "Timeline.Content";
TimelineTitle.displayName = "Timeline.Title";
TimelineDescription.displayName = "Timeline.Description";
TimelineShorthand.displayName = "Timeline";
// #endregion

import type { TimelineItemRecipe } from "@pisagor/recipes/timeline";
import { createContext } from "../../utils";

interface TimelineItemContextValue {
  slots: TimelineItemRecipe;
}

export const { TimelineItemContext, useTimelineItem } =
  createContext<TimelineItemContextValue>()({
    name: "TimelineItem",
  });

import {
  TimelineContent,
  TimelineDescription,
  TimelineIndicator,
  TimelineItem,
  TimelineRoot,
  TimelineSeparator,
  TimelineShorthand,
  TimelineTitle,
} from "./timeline";

export type {
  TimelineContentProps,
  TimelineDescriptionProps,
  TimelineIndicatorProps,
  TimelineItemProps,
  TimelinePresetItem,
  TimelineProps,
  TimelineRootProps,
  TimelineSeparatorProps,
  TimelineTitleProps,
} from "./timeline";

export const Timeline = Object.assign(TimelineShorthand, {
  Content: TimelineContent,
  Description: TimelineDescription,
  Indicator: TimelineIndicator,
  Item: TimelineItem,
  Root: TimelineRoot,
  Separator: TimelineSeparator,
  Title: TimelineTitle,
});

