import {
  type ToggleGroupItemProps,
  ToggleGroup as ToggleGroupPrimitive,
  type ToggleGroupRootProps as ToggleGroupPrimitiveRootProps,
} from "@ark-ui/react/toggle-group";
import { toggleGroupRecipe } from "@pisagor/recipes/toggle-group";
import type { ReactNode } from "react";
import { useMemo } from "react";
import { Toggle } from "../toggle";
import {
  ToggleGroupContext,
  type ToggleGroupContextProps,
  useToggleGroup,
} from "./toggle-group.context";

// #region Types
interface ToggleGroupPresetItem {
  value: string;
  children: ReactNode;
  disabled?: boolean;
}

export interface ToggleGroupRootProps
  extends Omit<ToggleGroupPrimitiveRootProps, "onValueChange">,
    Omit<ToggleGroupContextProps, "slots"> {
  onValueChange?: (value: string | string[]) => void;
  /**
   * Style recipe. Defaults to `toggleGroupRecipe` from `@pisagor/recipes/toggle-group`.
   *
   * @defaultValue toggleGroupRecipe
   */
  recipe?: typeof toggleGroupRecipe;
}

export interface ToggleGroupProps
  extends Omit<ToggleGroupRootProps, "children"> {
  items?: ToggleGroupPresetItem[];
}

// #endregion

// #region Parts
export function ToggleGroupRoot({
  orientation = "horizontal",
  size = "md",
  variant = "ghost",
  multiple = true,
  children,
  spacing = 0,
  onValueChange,
  recipe = toggleGroupRecipe,
  className,
  style,
  ...rest
}: ToggleGroupRootProps) {
  const slots = useMemo(() => recipe({ orientation }), [orientation, recipe]);

  return (
    <ToggleGroupContext value={{ size, slots, spacing, variant }}>
      <ToggleGroupPrimitive.Root
        {...rest}
        className={slots.base({ className })}
        multiple={multiple}
        onValueChange={
          onValueChange ? (details) => onValueChange(details.value) : undefined
        }
        orientation={orientation}
        style={{
          ...style,
          "--gap": spacing,
        }}
      >
        {children}
      </ToggleGroupPrimitive.Root>
    </ToggleGroupContext>
  );
}

export function ToggleGroupItem({
  value,
  className,
  ...rest
}: ToggleGroupItemProps) {
  const { slots, variant, size, spacing } = useToggleGroup();

  return (
    <ToggleGroupPrimitive.Item asChild value={value}>
      <Toggle
        {...rest}
        className={slots.item({ className })}
        data-spacing={spacing}
        data-variant={variant}
        size={size}
        variant={variant}
      />
    </ToggleGroupPrimitive.Item>
  );
}
// #endregion

// #region Shorthand
export function ToggleGroupShorthand({ items, ...rest }: ToggleGroupProps) {
  return (
    <ToggleGroupRoot {...rest}>
      {items?.map((item) => (
        <ToggleGroupItem
          disabled={item.disabled}
          key={item.value}
          value={item.value}
        >
          {item.children}
        </ToggleGroupItem>
      ))}
    </ToggleGroupRoot>
  );
}
// #endregion

// #region Display Names
ToggleGroupRoot.displayName = "ToggleGroup.Root";
ToggleGroupItem.displayName = "ToggleGroup.Item";
ToggleGroupShorthand.displayName = "ToggleGroup";
// #endregion

import type { ToggleGroupRecipe } from "@pisagor/recipes/toggle-group";
import { createContext } from "../../utils";
import type { ToggleProps } from "../toggle";

export interface ToggleGroupContextProps
  extends Pick<ToggleProps, "variant" | "size"> {
  /**
   * Gap between items.
   *
   * @defaultValue 0
   */
  spacing?: number;
  slots: ToggleGroupRecipe;
}

export const { ToggleGroupContext, useToggleGroup } =
  createContext<ToggleGroupContextProps>()({
    name: "ToggleGroup",
  });

import {
  ToggleGroupItem,
  ToggleGroupRoot,
  ToggleGroupShorthand,
} from "./toggle-group";

export type { ToggleGroupItemProps } from "@ark-ui/react/toggle-group";

export type { ToggleGroupProps, ToggleGroupRootProps } from "./toggle-group";

export const ToggleGroup = Object.assign(ToggleGroupShorthand, {
  Item: ToggleGroupItem,
  Root: ToggleGroupRoot,
});

