import { Portal } from "@ark-ui/react/portal";
import type {
  TooltipArrowProps,
  TooltipContentProps,
  TooltipContextProps,
  TooltipPositionerProps,
  TooltipRootProps as TooltipPrimitiveRootProps,
  TooltipTriggerProps,
} from "@ark-ui/react/tooltip";
import { Tooltip as TooltipPrimitive } from "@ark-ui/react/tooltip";
import {
  type TooltipRecipeSlot,
  tooltipRecipe,
} from "@pisagor/recipes/tooltip";
import type { ReactElement, ReactNode } from "react";
import type { VariantClassNames } from "../../internal/types";
import { TooltipContext, useTooltip } from "./tooltip.context";

// #region Types
export interface TooltipRootProps extends TooltipPrimitiveRootProps {
  /**
   * Style recipe. Defaults to `tooltipRecipe` from `@pisagor/recipes/tooltip`.
   *
   * @defaultValue tooltipRecipe
   */
  recipe?: typeof tooltipRecipe;
}

type TooltipContextApi = Parameters<TooltipContextProps["children"]>[0];

export type TooltipTriggerHandleProps = ReturnType<
  TooltipContextApi["getTriggerProps"]
>;

export type TooltipTriggerHandle = (
  props: TooltipTriggerHandleProps,
) => ReactElement;

type TooltipClassNames = VariantClassNames<TooltipRecipeSlot>;

export interface TooltipProps extends Omit<TooltipRootProps, "children"> {
  /** Trigger element or render function that receives trigger props from the handle API */
  children: ReactElement | TooltipTriggerHandle;
  /** Tooltip text or content */
  content: ReactNode;
  /** Slot class names */
  classNames?: TooltipClassNames;
  /** Extra props forwarded to the tooltip arrow element */
  arrowProps?: Omit<TooltipArrowProps, "children" | "className">;
  /** Extra props forwarded to the tooltip content element */
  contentProps?: Omit<TooltipContentProps, "children" | "className">;
  /** Extra props forwarded to the tooltip positioner element */
  positionerProps?: Omit<TooltipPositionerProps, "children" | "className">;
  /** Extra props forwarded to the tooltip trigger element */
  triggerProps?: Omit<
    TooltipTriggerProps,
    "asChild" | "children" | "className"
  >;
}
// #endregion

// #region Parts
function TooltipRoot({
  closeDelay = 150,
  openDelay = 400,
  positioning = { placement: "top" },
  children,
  recipe = tooltipRecipe,
  ...rest
}: TooltipRootProps) {
  const slots = recipe();

  return (
    <TooltipContext value={{ slots }}>
      <TooltipPrimitive.Root
        {...rest}
        closeDelay={closeDelay}
        openDelay={openDelay}
        positioning={positioning}
      >
        {children}
      </TooltipPrimitive.Root>
    </TooltipContext>
  );
}

function TooltipTrigger({
  asChild = true,
  children,
  ...rest
}: TooltipTriggerProps) {
  return (
    <TooltipPrimitive.Trigger {...rest} asChild={asChild}>
      {children}
    </TooltipPrimitive.Trigger>
  );
}

function TooltipPositioner({ children, ...rest }: TooltipPositionerProps) {
  return (
    <TooltipPrimitive.Positioner {...rest}>
      {children}
    </TooltipPrimitive.Positioner>
  );
}

function TooltipContent({ children, className, ...rest }: TooltipContentProps) {
  const { slots } = useTooltip();

  return (
    <TooltipPrimitive.Content
      {...rest}
      className={slots.content({ className })}
    >
      {children}
    </TooltipPrimitive.Content>
  );
}

function TooltipArrow({ children, className, ...rest }: TooltipArrowProps) {
  const { slots } = useTooltip();

  return (
    <TooltipPrimitive.Arrow {...rest} className={slots.arrow({ className })}>
      {children}
    </TooltipPrimitive.Arrow>
  );
}
// #endregion

// #region Closed
export function Tooltip({
  arrowProps,
  children,
  content,
  contentProps,
  positionerProps,
  triggerProps,
  classNames,
  ...rest
}: TooltipProps) {
  const trigger =
    typeof children === "function" ? (
      <TooltipPrimitive.Context>
        {(api) => children(api.getTriggerProps())}
      </TooltipPrimitive.Context>
    ) : (
      <TooltipTrigger {...triggerProps}>{children}</TooltipTrigger>
    );

  return (
    <TooltipRoot {...rest}>
      {trigger}

      <Portal>
        <TooltipPositioner {...positionerProps}>
          <TooltipContent {...contentProps} className={classNames?.content}>
            <TooltipArrow {...arrowProps} className={classNames?.arrow}>
              <TooltipPrimitive.ArrowTip />
            </TooltipArrow>

            {content}
          </TooltipContent>
        </TooltipPositioner>
      </Portal>
    </TooltipRoot>
  );
}
// #endregion

// #region Display Names
TooltipRoot.displayName = "Tooltip.Root";
TooltipTrigger.displayName = "Tooltip.Trigger";
TooltipPositioner.displayName = "Tooltip.Positioner";
TooltipContent.displayName = "Tooltip.Content";
TooltipArrow.displayName = "Tooltip.Arrow";
Tooltip.displayName = "Tooltip";
// #endregion

import type { TooltipRecipe } from "@pisagor/recipes/tooltip";
import { createContext } from "../../utils";

interface TooltipContextValue {
  slots: TooltipRecipe;
}

export const { TooltipContext, useTooltip } =
  createContext<TooltipContextValue>()({
    name: "Tooltip",
  });

export type {
  TooltipArrowProps,
  TooltipContentProps,
  TooltipPositionerProps,
  TooltipTriggerProps,
} from "@ark-ui/react/tooltip";

export type {
  TooltipProps,
  TooltipTriggerHandle,
  TooltipTriggerHandleProps,
} from "./tooltip";
export { Tooltip } from "./tooltip";

